"""Finite shared constructor selection from prepared topology, never positions."""

KINDS = ('single', 'paired', 'seam', 'logical')


def owner_program_kinds(site_count, pairs=(), clusters=(), seams=()):
    """Return the exact patch leaders and their constructor kinds.

    Inputs use the existing private site indices. Logical ownership supersedes
    an ordinary physical ring; seam selection has the original dispatch's
    priority over paired selection. Geometry edits never enter this function.
    """
    if type(site_count) is not int or site_count < 0:
        raise ValueError('Invalid prepared site count')
    def checked(group):
        group = tuple(group)
        if (not group or len(set(group)) != len(group) or
                any(type(i) is not int or not 0 <= i < site_count for i in group)):
            raise ValueError('Invalid prepared owner members')
        return group
    owners = {i:'single' for i in range(site_count)}
    for pair in pairs:
        a, b = checked(pair)
        if a not in owners or b not in owners:
            raise ValueError('Repeated paired owner member')
        owners[a] = 'paired'; del owners[b]
    for group in clusters:
        members = checked(group); leader = min(members)
        for i in members:
            if i not in owners:
                raise ValueError('Overlapping prepared patch ownership')
        for i in members: del owners[i]
        owners[leader] = 'logical'
    for i in seams:
        checked((i,))
        if i in owners and owners[i] != 'logical': owners[i] = 'seam'
    return dict(sorted(owners.items()))
